
.wizard-root {
  position: relative;
  padding-bottom: 8px;
  &::before {
    content: '';
    position: absolute;
    top: -20px; left: -16px; right: -16px; bottom: -32px;
    background: radial-gradient(circle at center, rgba(42, 34, 22, 0.2) 0%, transparent 70%);
    pointer-events: none;
    z-index: -1;
  }
}

/* ═══ Header ═══ */
.wizard-header {
  text-align: center;
  margin-bottom: 20px;
}

.wizard-title {
  font-family: var(--font-title);
  font-size: 28px;
  color: var(--zx-text);
  letter-spacing: 8px;
  margin-right: -8px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.title-seal {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px; height: 34px;
  background: var(--zx-red);
  color: #111;
  font-size: 22px;
  border-radius: 4px;
  letter-spacing: 0;
  margin-right: 12px;
  transform: rotate(-6deg);
  box-shadow: 0 0 16px var(--zx-red-glow);
}

.title-accent {
  width: 60px; height: 1px;
  margin: 12px auto 8px;
  background: linear-gradient(90deg, transparent, var(--zx-red), transparent);
}

.wizard-subtitle {
  font-size: 11px;
  color: var(--zx-text-muted);
  letter-spacing: 3px;
}

/* ═══ 固定档案卡 ═══ */
.档案卡 {
  padding: 12px 16px;
  border: 1px solid var(--zx-border);
  background: rgba(158, 42, 43, 0.03);
  margin-bottom: 20px;
}

.档案行 {
  display: flex;
  align-items: baseline;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 6px;

  &:last-of-type { margin-bottom: 0; }
  &.出身行 { display: flex; }
}

.档案键 {
  font-size: 10px;
  font-family: var(--font-title);
  color: var(--zx-red);
  letter-spacing: 2px;
  flex-shrink: 0;
}

.档案值 {
  font-size: 13px;
  font-family: var(--font-title);
  color: var(--zx-text);
  letter-spacing: 1px;

  &.出身 { font-size: 11px; color: var(--zx-text-sub); letter-spacing: 0.5px; }
}

.档案注 {
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px dashed var(--zx-border-light);
  font-size: 10.5px;
  color: var(--zx-text-muted);
  line-height: 1.7;
}

/* ═══ 属性配置 ═══ */
.step-card {
  animation: cardIn 0.3s ease both;
}
@keyframes cardIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: none; }
}

.step-heading {
  font-family: var(--font-title);
  font-size: 20px;
  color: var(--zx-text);
  letter-spacing: 4px;
  font-weight: normal;
  margin-bottom: 12px;
}

.method-bar {
  display: flex;
  gap: 6px;
  margin-bottom: 16px;
}

.method-btn {
  flex: 1;
  padding: 8px 0;
  border: 1px solid var(--zx-border);
  border-radius: 0;
  background: transparent;
  color: var(--zx-text-muted);
  font-family: var(--font-title);
  font-size: 13px;
  cursor: pointer;
  transition: all 0.3s;
  letter-spacing: 2px;

  &.active {
    border-color: var(--zx-red);
    color: var(--zx-red);
    background: rgba(158, 42, 43, 0.05);
    box-shadow: inset 0 0 10px rgba(158, 42, 43, 0.1);
  }

  &:hover:not(.active) {
    border-color: var(--zx-text-muted);
    color: var(--zx-text-sub);
  }
}

.attr-grid {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 12px;
}

.attr-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.attr-label {
  width: 90px;
  font-size: 13px;
  font-family: var(--font-title);
  color: var(--zx-text-sub);
  letter-spacing: 1px;
  flex-shrink: 0;
}

.attr-input {
  width: 48px;
  padding: 4px 0;
  border: none;
  border-bottom: 1px solid var(--zx-border);
  background: transparent;
  color: var(--zx-text);
  font-family: var(--font-title);
  font-size: 16px;
  text-align: center;
  outline: none;
  flex-shrink: 0;

  &:focus { border-bottom-color: var(--zx-red); }
  &:disabled { opacity: 0.6; }
}

.attr-bar-track {
  flex: 1;
  height: 2px;
  background: var(--zx-border);
  border-radius: 0;
  overflow: hidden;
}

.attr-bar-fill {
  height: 100%;
  background: var(--zx-gold-dim);
  border-radius: 0;
  transition: width 0.3s cubic-bezier(0.2, 0.8, 0.2, 1);

  &.low { background: rgba(140, 38, 38, 0.3); }
  &.high { background: var(--zx-red); box-shadow: 0 0 8px var(--zx-red-glow); }
}

.points-remaining {
  font-size: 13px;
  font-family: var(--font-title);
  color: var(--zx-text-sub);
  margin-bottom: 12px;
  letter-spacing: 1px;

  &.warn { color: var(--zx-gold); }
  &.over { color: var(--zx-red); }
}

.bonus-box {
  padding: 12px 16px;
  border: 1px solid var(--zx-border);
  border-radius: 0;
  background: rgba(158, 42, 43, 0.03);
  margin-bottom: 16px;
}

.bonus-title {
  font-size: 11px;
  font-family: var(--font-title);
  color: var(--zx-red);
  letter-spacing: 2px;
  margin-bottom: 8px;
}

.bonus-tag {
  display: inline-block;
  font-size: 11px;
  padding: 4px 10px;
  margin: 4px 6px 4px 0;
  border: 1px solid var(--zx-red);
  background: rgba(158, 42, 43, 0.05);
  color: var(--zx-text);
  font-family: var(--font-title);
}

.step-footer {
  margin-top: 16px;
  display: flex;
  justify-content: flex-end;
}

.btn-advance {
  padding: 10px 28px;
  border: 1px solid var(--zx-border);
  border-radius: 6px;
  background: rgba(201, 168, 76, 0.08);
  color: var(--zx-text);
  font-family: var(--font-title);
  font-size: 13px;
  letter-spacing: 2px;
  cursor: pointer;
  transition: all 0.25s;

  &:hover:not(:disabled) {
    border-color: var(--zx-gold);
    background: rgba(201, 168, 76, 0.15);
    box-shadow: 0 0 12px rgba(201, 168, 76, 0.15);
  }

  &:disabled {
    opacity: 0.35;
    cursor: not-allowed;
  }
}
